cd /opt/nxeon && node -e '
const fs=require("fs");
const s=fs.readFileSync("lib/ai-build.ts","utf8");
// count PromptTemplate entries roughly by counting "category:" inside PROMPTS
const prompts=s.split("export const PROMPTS")[1].split("export const GUIDES")[0];
const ids=[...prompts.matchAll(/id: "([^"]+)"/g)].map(m=>m[1]);
console.log("PROMPT count:", ids.length);
// per category
const cats=[...prompts.matchAll(/category: "([^"]+)"/g)].map(m=>m[1]);
const counts={};cats.forEach(c=>counts[c]=(counts[c]||0)+1);
console.log("per category:", counts);
console.log("first id:", ids[0]);
'

cd /opt/nxeon && npx tsx -e '
import { PROMPTS } from "./lib/ai-build.ts";
let bad=0;
for(const p of PROMPTS){
  const toks=[...p.prompt.matchAll(/\{([A-Z_]+)\}/g)].map(m=>m[1]);
  const keys=new Set(p.placeholders.map(x=>x.key));
  const uniqToks=new Set(toks);
  for(const t of uniqToks){ if(!keys.has(t)){ console.log("MISSING KEY for token",t,"in",p.id); bad++; } }
  for(const k of keys){ if(!uniqToks.has(k)){ console.log("UNUSED placeholder",k,"in",p.id); bad++; } }
  if(!p.prompt.trim().endsWith("preview it.") && !/tell me/.test(p.prompt)) { console.log("no run instruction",p.id); }
}
console.log(bad===0?"ALL PLACEHOLDERS MATCH":"ISSUES:"+bad);
' 2>&1 | tail -20
